) AS (
  VALUES 
    (150::BIGINT, 'Si reemplazaras a este profesor por un robot que esta manejado con chatgpt, probablemente daría mejores clases y organizaría mejor el curso que este caballo. Increíble que sea un profesor universitario. Todo lo hace con IA y se comporta muy raro. Perdida de tiempo!!'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-10-13T00:00:00+00:00'::TIMESTAMPTZ, '604f8ad095d438a5d80218c579c924a413d16a27c536152fd2c946aad94099c3'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'De los peores profesores con el que he tenido clase, no explica claro, baja puntos por absolutamente todo y hace todos los documentos con IA. Además de la incomodidad que generan algunos de sus comentarios.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2026-08-12T00:00:00+00:00'::TIMESTAMPTZ, 'd8b1b4cc0218b4a51ba61768b367ea02a1cb1257bb2e38bf2278d305e8f68d34'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Pésimo profesor, no da clases, todo se lo hace chatgpt, no responde dudas y es un prepotente desagradable que disfruta de decirle ignorantes a sus estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-05-15T00:00:00+00:00'::TIMESTAMPTZ, 'fc86ed8e3a2bc04c2aaf2e969456df660f389a66477a705f258493255e47f7dd'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Es un maldito subnormal, sus compañeros lo vomitan y los estudiantes más. Es el ser más mediocre que uno puede tener como profesor. No entiendo como puede trabajar en una universidad.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-03-26T00:00:00+00:00'::TIMESTAMPTZ, '42143c677a477ab8b6dee698b77a5ec1a71433bb63d80ac2f242da3ffdae3519'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Llevo tiempo conociendo a Randy, he llegado a la cruda conclusión de que el puede ser una IA, su lenguaje expresivo puede llegar a parecerse a Chimbot en su modo mas humano, lo cual me llega a hacer muy feliz, sus trabajos parecieran generados por IA pero es su forma de hablar. Amenlo'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2026-03-19T00:00:00+00:00'::TIMESTAMPTZ, 'b291fdb7eea3b0494e9b3d5dde17d0ee69c373dbd8d73e6ce5f3c2a9e3f3c5aa'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'absolutamente todos sus documentos son hechos con IA no revisa ni el documento sale de chat gpt y lo pega en teams'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2026-03-19T00:00:00+00:00'::TIMESTAMPTZ, 'ada1c29b6ca2abd147d66cfb612f6f00a33704d861c8e26130164cb239120295'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Tiene una personalidad un poco peculiar, demuestra conocimiento del tema pero se desvía mucho y habla por horas sobre cosas realmente innecesarias y en ellas cuenta chistes qué comprometen a todos a reírse porque solo él se ríe solo. Permite el apoyo con IA y asigna presentaciones extensas.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2026-02-20T00:00:00+00:00'::TIMESTAMPTZ, '71ba5967334d5ddb721d58e7499df7567e2197b0093c007bdcbd8e4e9ce70bb0'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Es verdad lo de que tiene ciertas actitudes extrañas. El profe realmente sabe de lo que habla conoce del tema y como desarrollarlo, pero no logra explicarlo bien a la clase, se hace confuso y todo es grupal. Las instrucciones las llega a dar hasta con los emojis de ChatGPT.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2025-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'c16a0f3bc1a40481da566a51b3f7a2e32843cc65693f4dcc81b3bd363a0a9e18'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'El profesor tiene actitudes muy raras y en ciertos comentarios no tienen balance con ser gracioso y respetuoso.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-10-11T00:00:00+00:00'::TIMESTAMPTZ, '173a4ece9591afe0f6616d9f6fbf25c3e39d82dddeede942a4476dfea85b8b89'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Pésimo docente, si quiere aprender con él no es, si quiere pasar a costa de vivir las clases más innecesarias de la historia cosa suya. Todo se hace en grupo y las instrucciones de los trabajos suelen ser malas. Además, tiene actitudes raras.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2025-07-24T00:00:00+00:00'::TIMESTAMPTZ, 'b34049112d184f1e23e88f08c8303106443cd5daf4a8166a3614c3541947f73a'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Muy fácil pasar, solo debe de poner atención a las instrucciones porque no es muy claro a veces. Además casi todo se hace en grupo'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'b822b49316b83dff123327d25b9eceeb700f6ce25004e210a5643bf8aa2a05dc'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Da la clase completamente en grupos entonces uno va desde el día 1 dependiendo de otros. Igual esto hace que todo sea más fácil en verdad. Como otros dicen es muy fácil pero sí se vuelve un despiche total porque el profe es muy desorganizado y muy poco claro con las instrucciones. No se aprende'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2025-07-10T00:00:00+00:00'::TIMESTAMPTZ, '0d764b9abb01138ec8849e606ebfe69efe4eb440a5db11a8bcd6874ed5c9d9ec'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Es extremadamente fácil pasar, pero no se aprende absolutamente nada.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, '10876746738eb5de98f9067318460afbc761cd5a2f14ed183497a87e03822c94'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Es demasiado fácil pasar, tanto que lo recomiendo por eso. A veces da instrucciones confusas entonces hay que ponerle mucha atención cuando las da.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-20T00:00:00+00:00'::TIMESTAMPTZ, '8f9732eaf9886f514c974ece490e1045e35d7ba01dfc66ef7d1a6c24e67b072d'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'El profe es medio raro, hace absolutamente todo con ChatGPT, la clase es super aburrida pero se pasa fácil. Ponga atención cuando da las instrucciones porque son medias confusas, pero todo lo trabaja en grupos entonces ahí más o menos uno se ubica.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2025-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'c5c71c44af44af0c643058b6b440555fb0bd393ea614c3c12681a65a7c1c5543'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'el profe como que no está muy interesado en enseñar, todos los trabajos los hace con chat gpt pero si usted le pregunta el le atiende la duda procurando que usted entienda. talvez puede sentir que es una persona intimidante pero si no le quedó claro vuelva a preguntar. es fácil pasar con el el curso'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2025-06-04T00:00:00+00:00'::TIMESTAMPTZ, '1f64e3ff0af7e08f1a36cd2538036c539f40c31b6b19abdbe9a68242c6667d87'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'No es muy agradable, pero por lo menos los trabajos que deja se terminan rápido, y no es tan cargado. Se pasa fácil el curso.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2025-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'f3ad8ef3857f1d6ab31a2a1c9b6e03c7fb3e31309494ca46e5c215e6ce3a84f0'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Para iniciar la clase es completamente en grupo por lo que se debe acostumbrar a eso. El profe hace todos los trabajos con chatGPT y no se ve muy interesado en brindar ayuda por experiencia propia pero por otro lado los trabajos son cortos y faciles ademas que en grupo se realizan sumamente rapido'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2025-03-27T00:00:00+00:00'::TIMESTAMPTZ, '7c1a7310b39d04f3eb339859e1635e1216bcbbf4dd2ae539d6a012e7e38183bd'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Bro, es la primera clase que recibo, y me cayó bien, uno se la pasa riéndo, las clases de él son para desestresarse, no tanto para aprender, buena gente, lo recomiendo, ya que hay que desestresarse en el tec'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2025-02-20T00:00:00+00:00'::TIMESTAMPTZ, '3c7c3234b7997511f3a8498a545e306be112929459cb28e77e7bdf11c89f10d8'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'La verdad es que el profe es un poco necio en las clases y deja bastantes tareas, que aunque son cortas siempre hay que hacerlas y si se acumulan son un problema. Fuera de eso y de dar las clases de maneras peculiares, el mae no lo va joder mucho más, es un curso que se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, '3b22f3a7ba693a588112862447a6bfdb2c4e318d61e0e0249867b0cd373cceaf'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'NO LO HAGAN, por más que sea el único docente que tengan NO LO MATRICÚLEN. El propósito de llevar una clase en la u es aprender y con ese señor no van a aprender nada porque todo lo hace a punta de IA. Malas instrucciones y pésimo manejo de teams'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2024-11-18T00:00:00+00:00'::TIMESTAMPTZ, '8e95c0ec6ead448062e7296acc82fe427db233632d02479f3ec403ff74425ad4'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Todas su clases son preparadas por chat gpt. No sabe ensenar y no se como obtuvo su titulo como docente. Nada simpatico y terrible con sus instrucciones. No tiene modales. Pero, si se pasa muy facilmente ya que no revisa nada.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2024-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'e4f25af1247bf9345ed22a042c4fde96b78df83a39734a7613b10faee5893506'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Es facil. Este curso en verano fue tranquilo. Trabajos simples que no quitan nada de tiempo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-14T00:00:00+00:00'::TIMESTAMPTZ, '7c5b102a6d4065f9ab33ada51c3ac7d3a48974efa529662fd519176ee4acf576'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Mira, el bro es medio raro, se ríe como si se fuera a ahogar y da vibes extraños, pero pasar con él es super fácil. Lo más enredado es que él quiere que sea todo en Teams, pero sus clases son muy sencillas y deja trabajos muy sencillos, literalmente lo más duro es ver donde entregarlo'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2024-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'b7a8526eb2f136c30814bdba959c0b28fc7a79a0f8be9ab9014c79da58093bd8'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Él es cero claro y sus indicaciones son enredadas, clases superaburridas, él a veces se va y es todo un desorden. Lo bueno es que prácticamente todo se hace en clase y en grupo y él deja salir temprano. No lo recomiendo, pero si tiene que llevarlo con él lo pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-08-09T00:00:00+00:00'::TIMESTAMPTZ, 'c760554f9ba249b5f5723e6fa0e7038290f2d30a18a3cfda40a5f782de526630'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'El profe es desordenado. Al principio no da la rúbrica y después la cambia. Usted tiene que apuntar los trabajos y las entregas porque el las dice verbalmente y después se le olvida. Pero en general, con ir a todas las clases y apuntar bien las fechas de entrega, pasa. Además, no pasa lista.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2024-06-16T00:00:00+00:00'::TIMESTAMPTZ, '776447f428e470052964a591d5e699acb803d0f4ba5ae625ec42f5624db30b80'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Si tienen la oportunidad de matricular clases con él, desaprovéchenla.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-05-27T00:00:00+00:00'::TIMESTAMPTZ, '72ed412415d098bc4906a4abc45c44464cc422a7d644b0dd964bedcfeeee0dd8'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'En verano no se complica mucho con el curso y hace las clases cortas y deja tareas sencillas.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Asistencia obligatoria']::TEXT[], '2024-01-26T00:00:00+00:00'::TIMESTAMPTZ, '730b5653832e6fd1140e50c1adce78af89db84493f546f62ef774a77beaed36b'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Es buen profesor, sus clases son cortas. Deja tareas para cada semana pero son muy cortas y se hacen fácil. Si quiere que el curso le quite el mínimo de tiempo lleve con él, su clase se resume en oírlo hablar de si mismo y reírse solo, pero en si enseña algo.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'ce9eb75532c8474e9fd8ef5c32528e90c1e4a23c5ec4f50fa396d0c5285bbcfe'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Es una buena opción si lo que usted busca es que un curso no le tome tiempo y quitárselo del paso, pero no se aprende mucho porque lo que el profe manda son tareas muy rápidas y las clases son escucharlo hablar de su vida. Todos pasan con 100.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'c243cf0d40486f726dba3b5a46deca5bb4422a28fd492f5f8617ec4b8440fa72'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '006106db2a56288e4f4f283b162b79af9cce897eb505360d38e78892498a6a66'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Es un buen profesor, pasos para pasar y no tener problemas: 1. Vaya a clases 2. Haga los trabajos a tiempo, sea ordenado con las entregas y ya. 3. Sea respetuoso. Buen profesor en general.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '38672c6748b916122a9f64fc446fa00833a6e98e19e17906deffdf615079a84f'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Mientras le guste trabajar en grupo, y entregue todo, pasa como si nada, las tareas no tienen ni que estar bien hechas'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2023-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'd1e1d50d553a72188bfe987c14580f9a27aa4f2d896f2861e693a0ed70f08898'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Si tiene problemas para trabajar en grupo mejor no matricule, va a sufrir. Fuera de eso buen profe, se hace un colocho por que usa Teams y tiene como 10 espacios de entrega para las tareas pero si va a las clases, no se pierde tanto. Aunque no pase lista VAYA A CLASES, entregue todo y pasa.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2023-06-11T00:00:00+00:00'::TIMESTAMPTZ, '9e374ee519ec52895221164730e6ae772aa4a25b230753335e6229d977b618c3'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Simplemente manténgase haciendo las tareas al día y todo va a salir bien al final. Literalmente solo evalúa el orden y que las tareas estén hechas. Sin embargo, se enreda mucho al explicar. Habla muy lento.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos proyectos grupales']::TEXT[], '2023-06-07T00:00:00+00:00'::TIMESTAMPTZ, '634b72a96377d4b30413897fd9a6a0e1355676d77759713dc5699eec2359c28e'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Muy buen profesor, en caso de alguna duda te la resuelve muy rápido, además de que es muy compresivo con distintos temas que pueden afectar al estudiante, además sus tareas son cortas y muy fáciles, sin embargo, hay que tener un buen equipo de trabajo, para la presentación final.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-17T00:00:00+00:00'::TIMESTAMPTZ, '9a6abb7d3843c49d1f76f12c144db544ff23e6961027eb13f1836504e81d926b'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Con este profesor el curso es demasiado fácil, entiende que es un curso de solo un crédito y sus trabajos son muy fáciles. Lo único que hay que hacer es seguir bien las instrucciones de lo que pide.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-08T00:00:00+00:00'::TIMESTAMPTZ, '679ca4efda427f30a30f0d789619f6d8e5064627251dc4f1184a69d0b321c11d'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Con este profesor todo lo que hay que hacer es SEGUIR LAS INSTRUCCIONES y se pasa super fácil (en comparación con los otros grupos). Las clases son muy relajadas e interesantes. A veces se ahoga riéndose de sus propios chistes pero es normal.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2022-12-06T00:00:00+00:00'::TIMESTAMPTZ, '3d5641a019658d2ecb4b138d1dd027362519f6346641ddf1f4f58d21d37a555b'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Un curso súper sencillo de pasar, aunque si tiene bastantes trabajos pequeños. Si usted cumple con las instrucciones que él deja en los trabajos, casi garantizado que tiene una súper nota al final.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-02T00:00:00+00:00'::TIMESTAMPTZ, '849d97d603f320df73979865172fc296960ceb4f559974dde26f2d3e67ee0146'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Clases cortas y tareas fáciles de hacer que toman poco tiempo. Lo único es que es muy poco empático y no muestra interés cuando usted ocupa ayuda con algo.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'a0ba19fa1bdf159821b1270549e4f95d522dea4b0a2e7cea9a14d4a37ef1e9dc'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Juré que iba a perder el curso, porque en todas las clases decía que nadie sabía redactar o que todo lo hacíamos mal jaja, pero al final tuve 10, no entiendo cómo. Se pone pesado si le hacen preguntas en clase, casi no deja hablar (cero paciencia) pero mientras entregue todo, yo creo que uno pasa'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2022-07-11T00:00:00+00:00'::TIMESTAMPTZ, 'ec596c7dae52e9c1b2389e4f20fdc68da94457f396a672c2f57cb4a5e70892f3'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'El curso se pasa fácil pero la forma de enseñansa del profesor me chocó un poco, es muy directo, si uno le pregunta algo dice "busquenlo ustedes" aunque si enseña lo básico. Son muchas tareas algo cortas, puede ser pedante y siempre tiene la última palabra'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos proyectos grupales']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'ff98a828c61cf2decc0912078b700cd39d33e6230cbc66429080f97071f63985'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Llega a sentirse arrogante, muchas veces se niega a explicar. Cree que todo se entiende con las instrucciones, las cuales suelen ser poco claras. Poco claro a la hora de aclarar dudas.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2022-06-26T00:00:00+00:00'::TIMESTAMPTZ, '73ac461a040f0957eaba653b8920f593d302496fa7dbbde2c180fcd960671acc'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Súper fácil el curso con el profesor, si uno sigue las instrucciones al pie de la letra el curso se pasa solo'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2022-06-25T00:00:00+00:00'::TIMESTAMPTZ, '78954981778db185b13d7fa3b8e351cfd84a8ebcbeefebacf143813216bdca3e'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2022-06-25T00:00:00+00:00'::TIMESTAMPTZ, '3040fc4b56614aaf2801779ea4b06891c53847eb8b08241e8fab5b3b8edbfefc'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Cuando califica se contradice demasiado. Insiste en que no sabemos leer instrucciones y quiere que todo se haga al pie de la letra de las indicaciones confusas. Muchas tareas pequeñas cada semana que se vuelven tediosas, el curso es muy lento. Enseña a escribir de manera clara y concisa.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '1ff6550e7754efeba5f89bd8c07922ced2359dbde33dec685e197b193a346445'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2022-05-12T00:00:00+00:00'::TIMESTAMPTZ, '6f402817e12a97970398b845d4a3c0f67f8d7e58c08465ece167f596ce9aeb1f'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-12T00:00:00+00:00'::TIMESTAMPTZ, '08321a4cb51de37fa134b7a3c8c14f907fe6d390a695a92a28744f6d3106790f'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Es un pésimo profesor. No es claro con las indicaciones de sus trabajos y espera cosas perfectas. Insiste en trabajar en un formato incómodo, lento y confuso para el estudiante. Realiza comentarios que no vienen al caso en sus clases y se enzaña con las personas que llevan problemas en la misma.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2022-05-09T00:00:00+00:00'::TIMESTAMPTZ, 'd7cf246ecc1731e3c89d990041fab278fe2e9c282ebdf7c8d6a396c2034542d9'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2022-04-21T00:00:00+00:00'::TIMESTAMPTZ, '412f5642d23f205b776d38fa7eae2fb88abb7a1f769bcd4ac42f1b86d65084ab'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Es muy orgulloso, no explica bien y pide todo perfecto, para el nada esta bien, da muy poco apoyo a los estudiantes'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-04-07T00:00:00+00:00'::TIMESTAMPTZ, 'c5419368ddee6258181648a738669b32c28e5a587defcfa54247f7d7a31e9ad8'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Es un profesor demasiado arrogante. Al momento de calificar se contradice demasiado; puede decir que tenemos bien una tarea y la siguiente semana dice que dicha tarea está mal. No explica, para él la manera de aprender es autónoma. Pésimo profesor.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2022-04-07T00:00:00+00:00'::TIMESTAMPTZ, 'd5db6086a6767f5b5cc49953450e92691054809ac2aab39a545d564d0b3fd22e'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Demasiado fácil el curso con este profesor. Los trabajos son hacer videos cortos de 2-3 minutos hablando sobre cosas muy específicas, lo que facilitan todo mucho más. Hay proyecto grupal, y el mismo hace los grupos, pero todo bien. No dude en matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico', 'Aspectos de calificación claros']::TEXT[], '2022-02-05T00:00:00+00:00'::TIMESTAMPTZ, '1706b172f9d96530035367a2ef3e38dc5c2b90164e68d5e31bc34b1199f1469c'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'El profe es super buena nota, las clases son muy faciles, deja trabajos muy sencillos, facil ganarse los puntos, las clases son cortas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'b2ef65e8686aff51c32cae812b9fd4d9c34687e0d807203bcd43b21caf42ff89'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Sus clases eran demasiado rápidas, todo el curso en general demasiado fácil, se aprende y fue muy entretenido.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'f8be5a043f6f77b25db53b23d0e78b4c42476eb992439feda60b0f8ab1e666a6'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'A veces no es muy claro con las asignaciones que deja pero de igual forma son muy fáciles y simples, también en ciertos casos se contradice pero no es algo muy importante. Con este profe el curso se pasa fácil, sí recomiendo matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes']::TEXT[], '2021-11-24T00:00:00+00:00'::TIMESTAMPTZ, '16ba48388918eeddfb8ed733bc7db5f8c0a7a14486f4a143f43b8efb7b0f88c4'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, '10/10. Entiende que no sólo llevamos su curso, deja tareas semanales súper cortas, y en cuanto a la fecha de entrega es súper relajado. Los ejercicios que deja realmente son funcionales, ayudan a mejorar las habilidades de comunicación de una manera sencilla. Súper recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-20T00:00:00+00:00'::TIMESTAMPTZ, '0764b9735875fb228f0758a0481b8ef1b662cd61ad1f941b422adf54aa915996'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Es el mejor profesor, entiende que no solo llevamos el curso de él. Deja tareas todas las semanas, pero son muy fáciles, es super flexible con las entregas, no califica duro y las clases son cortas. Si quiere pasar el curso sin estrés y con buena nota, dele sin miedo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-11T00:00:00+00:00'::TIMESTAMPTZ, 'fb8816fc5ed19ee6273f11eab80e7a2e19033f3104583d8f7569028c06b5790c'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Si quiere pasar un buen rato y despejarse, matricule con el, es super buena gente aunque al principio parezca arrogante, pero es solo la impresion inicial, se aprende mucho, enseña a ser claro y conciso, los trabajos son grupales'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'f513a86e62da20fcbbc5c4784a950d8341b290cc1e7c772a54ab73ab34cdb525'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Afortunadx si le toca un buen equipo de trabajo, ya que deja tareas grupales e individuales (pequeñas) todas las semanas, es desordenado, insistente en seguir las instrucciones al pie de la letra, en las clases se desvía mucho del tema y son irrelevantes. No graba las clases. No es atento, ni amable'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, '928bb73058d266dcc22fda9ee8f4e578eb704b6472f7f689c511f9e36dd529d6'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Hay trabajo grupal e individual y bastantes tareas pequeñas por semana, termina la clase antes para que usted trabaje con su equipo. Las indicaciones son confusas pero al final todo se va aclarando, no revisa nada hasta las ultimas semanas. No califica duro, es facil pero puede ser aburrido.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '73e44955e410b57bc4f19260e84600b04031551a7b800d0f0873496b2affc14d'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'La clase es aburrida, deja unas 3 tareas por semana, pero son facilísimas. Califica super suave; sólo haga todo tal y como lo pide y pasa gratis. Responde rápido y se toma su tiempo para explicarle las cosas por aparte, porque en clase lo hace muy superficial.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '4ba5e194e6b29e2d32efa9f1a02674a9a25c2fbe78af8882b892133faf000551'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Vea, es fácil pasar con él, cuesta entenderle cuando explica las indicaciones en clases, pero si puede preguntarle mejor, es accesible con eso, aunque a veces se enreda. Entregue todo lo que pide a tiempo y no tendrá problema. No da risa y es extraño pero se pasa chill el curso'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2021-06-21T00:00:00+00:00'::TIMESTAMPTZ, '9afee8e94a9576e87ad5b7ffd803aae3905287c6a672f68ca8d4a05fa32073be'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'no lo recomiendo mucho, deja muchísimas tareas que al final son útiles para el trabajo final haciéndolo llevadero, pero su problema es que no las revisa! No explica bien lo que quiere y es duro para calificar así que posiblemente pierdan varios puntos de manera tonta en las entregas.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Pocos exámenes']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '9cfcee0344ebb78740c73294f19ab0a6c08e109df225a5a9c507dfd8946d1e8d'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Es bastante raro, de cómico no tiene nada, se ríe solo de sus propios chistes y nadie entiende. Con respecto al curso, la metodología que usa hace que no sea tan pesado y se pase fácil. Se enreda cuando explica, las instrucciones de trabajos son más claras. Si quiere pasar fácil, matricule con él.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-04T00:00:00+00:00'::TIMESTAMPTZ, '4eb24c7eb334a682a459a29bf8612325676d668c341a9e0e3d9f26781fbed86a'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Las clases son cortas pero se hacen eternas por el profesor. Es un payaso, muy aburrido y ridiculo. Las tareas son confusas, trata mal a los estudiantes y usa una manera de califcar y subir archivos muy confusa tambien. Pero el curso es facil de llevar y el no lo hace muy cargado'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2021-05-25T00:00:00+00:00'::TIMESTAMPTZ, '09d90f8037e457c9e8717e14a3a94a1fbfc6737db324a0424a6a6be4e784f13f'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'El curso es demasiado aburrido. Sin embargo, él lo hace un poco cómico y llevadero. Deja muchas tareas semanales, pero son básicamente la información para el texto final, así que ayuda mucho. Califica hasta el final, así que saber la nota en el transcurso del semestre es difícil'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2021-05-11T00:00:00+00:00'::TIMESTAMPTZ, '9d2eca3ea89b8c601112cf88a304c08139bdd135d1fb9127ff1e08fa344e81b5'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Super buena persona y super buen profe, eso si, saber como le va a uno a lo largo de curso no es muy comun, califica hasta el final los portafolios de trabajo que se van desarrollando clase por clase'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2021-05-07T00:00:00+00:00'::TIMESTAMPTZ, '4d61b2116f8da23daa4bc5dd4d24d351deb1413014648fe61d1076a08409a3cb'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Me encantó las clases con él, la verdad es muy buen profe sabe mucho y explica bastante claro. A veces se desvía cuando habla sobre otros temas pero hace la clase interesante y muy bonita.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '079f8f2bbdd2a5f2329c7a74da2b261a54a6c361e55b12b5bfffdd15767cdd37'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Sus clases duran 30 minutos en promedio y sólo deja tareas, pero son tareas muy sencillas y que realmente ayudan a desenvolverse al hablar.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muchas tareas', 'Aspectos de calificación claros']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '5576bb6a4da13d2f67761e767770dd1963f80504d7323c911232d77fbbe312ae'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Fue un curso muy fácil de pasar ya que las clases son muy cortas y el tiempo que sobra de la clase se la da a uno para que haga las tareas que deja para la semana, las cuales son muy muy simples de hacer.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'ef5e211363d6a5aab8c7916e2b88965587f48fdcab5d1ad660d60a097bbba02d'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'El profesor hace las clases cortas, deja tareas todas sencillas todas las semanas. Un curso muy pasable.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2021-01-13T00:00:00+00:00'::TIMESTAMPTZ, '49c330fce190ac9d53ac3d0eecc130126e7a2325cbf509451e463b55033a31a2'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'No ayuda mucho, muy confuso y hay que marcarle todo porque nunca encuentra nada pero se pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2020-09-02T00:00:00+00:00'::TIMESTAMPTZ, 'e61e4c7870ccd8202e197e2847c60ccd7aeec2d5b7ebc87a32b73749407a1a67'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Easy de pasar, en verano es super facil, muy bueno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, '213fe2b5dbcb683e361c1935870d9896afd6c13243379e8c17891d954ed1430b'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '4490a8db0d45e1d52b0e41256d1246bcaf521098026d8273bc6c4aadcabcd3fd'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Usa una aplicación súper rara para calificar, deja tareas cortas pero se hace un enruedo explicándolas. Califica suave entonces se pasa súper fácil. No se aprende mucho'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'dad34b0ab65c8e1cf1fd3cae66ef11e7de484027f0121a236eba38c8400b5119'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'No se aprende nada, las clases son un cermón de 2 horas , se pasa súper fácil si eso es lo que está buscando jaja.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'ba92fe7aa259da1228f5026cbcc7a4c2ae1767138834077fc0139ff31f35bc29'::TEXT, ARRAY[556]::BIGINT[]),
    (150::BIGINT, 'Hay que ser muy necio para quedarse con el. No se aprende mucho. Clases repetitivas. El sistema en donde sube las calificaciones es raro. Una risa super graciosa.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-23T00:00:00+00:00'::TIMESTAMPTZ, '0b9c9ddf393e8e8a740abaf9930508d4f846c72d3bbee70ab047877aaa374ab0'::TEXT, ARRAY[556]::BIGINT[]),
    (150::BIGINT, 'La verdad no lo recomiendo, o sea va a pasar fácil el curso pero el profe no enseña casi nada, califica como le de la gana y es aburrido. El curso fue básicamente entretenido por los compañeros, porque si no un bostezo.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2019-12-18T00:00:00+00:00'::TIMESTAMPTZ, 'f328f6c98de981c9ebb02acee95390247df154eb8edbbc303d3f27ce87f803f2'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Las clases son muy aburridas y repetitivas, pero al parecer es lo normal en este curso. Hay que hacer un esfuerzo demasiado grande para quedarse, ya que el explica los pasos de los trabajos muy detalladamente y los califica muy suave. Lo recomendaría para este curso, pero no se aprende mucho.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, '49c5bac934250aa96d281dde595e2c44c0af5a0d04b080f772600c2c69707fd5'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Buen profe, si quiere pasar el curso fácil matricule con él. Solo tome en cuenta que en ciertas exposiciones se pone estricto, y al inicio la aplicación en donde sube las notas puede ser un poco confusa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases largas']::TEXT[], '2019-11-10T00:00:00+00:00'::TIMESTAMPTZ, '57afa737bb856a66bc8d53763c5d9f9da719f463142b5a6b36e22e4d5124b843'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Es un profesor excelente, al principio su metodología de clase puede ser confusa, pero con el tiempo todo va a aclarándose. Sus proyectos son cortos sin embargo deben ser bien realizados (calidad ante cantidad). No faltar a clases puesto que deja muchas tareas cortas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2019-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'a654d65664c53f78f4a2d56e32b8e559ff21630abb5e57dde65b8e8c11bcbd38'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'cee96c93680e5a503213f5ddf5f5b38c015f18abe16a1c030f08aa388abd278e'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Excelente Profesor, las clases son bastante Relajadas, cuenta muchas anecdotas de su vida y deja pocos trabajos, no toma asistencia'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'cb7335157966a4e27ae7b2d059a3dfb5c55ad5be3a95b115ceea715a4bbb1a81'::TEXT, ARRAY[556]::BIGINT[]),
    (150::BIGINT, 'El curso no ayuda en nada a aprender sobre comunicación escrita, todo se basa en un par de trabajos y listo:'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'c5271f5d1b215b109655568d3c3728baee9d94eaf362f7bd7186ea49de5ccd9e'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Este curso se pasa muy facilmente, el profe sabe que no es un curso en el que uno se deba matar pasandolo. Lo unico malo de este profe es que a veces nos hacia ir para nada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'fea4c7a1ca94ccfd22d1be9a521b0c0ac23b554491ad1dba75ada932ad4b2d44'::TEXT, ARRAY[556]::BIGINT[]),
    (150::BIGINT, 'La primera mitad del curso es muy fácil, se enfoca en exposiciones y expresión oral. La segunda mitad también es fácil y se enofca en la propuesta e informe técnico. El profe muchas veces falta a clase sin previo aviso. La asistencia no es obligatoria y califica muy suave.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '1f94b960ec00810f100b638a2dd4dd33b26b9b876eb3e1c6ce835adbaf4205a6'::TEXT, ARRAY[556]::BIGINT[]),
    (150::BIGINT, 'Se pasa fácil, sus clases son interesantes, no deja muchos trabajos y los que deja suelen ser bastante sencillos. Es un buen profe para estar relajado en esta materia.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, '51deb5f473c138467b667e7e0593b614821e8ac48c5d653c3dd079d3c597c9b7'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Matriculé con el es un buen profe y el curso se pasa fácil y sin mucho esfuerzo, no deja tantos trabajos y los que deja son fáciles, no pasa lista, es lo más relajado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, '1da967cabc5a13e7823896d6efd89e844bd23f704c6fd271c67ffae62bec2b77'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Llévenlo con él si quieren pasar sin esfuerzo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-14T00:00:00+00:00'::TIMESTAMPTZ, '4933f72f9a043104c2ffd1c3393e71ab3841421720d00bdbe60259cc7337b14c'::TEXT, ARRAY[556]::BIGINT[]),
    (150::BIGINT, 'El profesor hace el curso bastante fácil, de 1 crédito como debe ser. Tiene que prepararse para hacerse el payaso eso sí. Lo recomiendo, especialmente si ya considera tener bases sólidas para una buena comunicación oral.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2018-12-23T00:00:00+00:00'::TIMESTAMPTZ, '6c23d82d8fcd6b25620bb5ef318d5d5cdf36fad7123f7506f06664401dcb5cd9'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'No hace el curso para nada pesado porque sabe que vale 1 crédito. Se aprende bastante, las clases son divertidas y se pasan rápido. Los trabajos son muy fáciles y se hacen rápido. El cuenta sus anécdotas, es pura vida y no califica duro. Super recomendado para esta clase. :)'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'b21fa33f3cfad55a2493d89b6067085c88e7e77853641ca6e96354bfac7e8bf0'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'El curso se pasa super fácil, los trabajos no se dura ni 10min en hacerlos. El profe es super vacilón y pasa contando anécdotas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'bdd7426b9d01b5cdcd2706bf2688966e03fd29a0c859a85f2bb39e314216de55'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'Super recomendado, casi no deja trabajos, explica bien y con ejemplos, siempre termina antes la clase, califica suave.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '1695d87cfae609f90da38220f65ec84bc795e8970ebb3b5b47545285003bf875'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Clases faciles y casi siempre no se hace nada, deja muchas tareas pero son fáciles. Un poco impuntual'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa']::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, '89d85af6a3770cd90a53c53baa00a8c169d3da1ddfe2148485e4f382afcd268b'::TEXT, ARRAY[556]::BIGINT[]),
    (150::BIGINT, 'Explica súper claro el cómo redactar correctamente. No le importa la cantidad de páginas sino la cantidad. Es una excelente persona'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-05T00:00:00+00:00'::TIMESTAMPTZ, '555d6adb84b6843d3cab2b1f442fa60a65c9e8436ef73d3d78e28d8e495b3947'::TEXT, ARRAY[554]::BIGINT[]),
