    (150::BIGINT, 'He is a good teacher.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-02-05T00:00:00+00:00'::TIMESTAMPTZ, '0c60c66c3987ed83f4566435bd9f80e73111f23f57cb7a0cb7d075855da5b18e'::TEXT, ARRAY[600]::BIGINT[]),
