    (150::BIGINT, 'Muy facil, deja muchas tareas para subirlas al facebook y a veces no crea los eventos. Es buena gente, un tanto impuntual y aburrida la clase... Pero se aprende y se pasa!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-14T00:00:00+00:00'::TIMESTAMPTZ, '9a24a3683e9e02dd42aa371ffb627e7cb5dabe4dde5a452d209f44589d8a3acd'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Profesor atento, desordenado, Aveces no sube los eventos al facebook y deja todo para el final, si embargo se lleva muy relax'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'af8b9bffdd4a82406f5231ec6e017ba8bfe384ac387a8893bd31bcd96a828189'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'es bueno, solo algo impuntual.. además es bastante fácil y no deja muchos trabajos..'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-30T00:00:00+00:00'::TIMESTAMPTZ, '29bbd62da5fb998eec28a1b23a00e7eb81bb393b3629a52a5c19b0fa92928b9e'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'b5a02bd26f77f6cf2f92b72f3a0e82d8c2167cbbdc80276abe3959cb4ac1dae4'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Es muy bueno, muy paciente, pero muy aburrido...'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-28T00:00:00+00:00'::TIMESTAMPTZ, '54a25d38210e4267456640329cb15fd0aa942b6025a6dc3eeb6fe2ae87afb981'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Es en extremo facil, pero es medio impuntual, es muy pura vida y la clase es entretenida, solo que si en serio quiere aprender no es muy recomendado'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'cec0263b694955f0d9f1addc2d909aa7d105a0453d9de66a76905a2ec75eb2f5'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'Hace la clase entretenida y es fácil de pasar pero si ud no sabe redactar y quiere aprender más, mejor matricule con otro profe.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-13T00:00:00+00:00'::TIMESTAMPTZ, '78c58ff8956d84ecad1cc570bbaabdd5a0534169d4fd14b4c67bdee29ed7547b'::TEXT, ARRAY[600]::BIGINT[]),
    (150::BIGINT, 'El mejor profe, hace el curso entretenido y cero pesado, es demasiado pura vida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '212b6ec139c11ce71c72b41379c3082d165e4a87015f2ad2b2d7a17e3eb1ec9a'::TEXT, ARRAY[556]::BIGINT[]),
    (150::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '103f42412bf3d0c96366b0de6d32e9af77a1da06cd523356a288bb654b3f073a'::TEXT, ARRAY[554]::BIGINT[]),
    (150::BIGINT, 'El mejor profesor de esa escuela'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'e516eb8534c4c0bd18ee081b06ace0a8f009f224052a09b2f2b81cb05ebf3b6a'::TEXT, ARRAY[600]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
